LogicDefinition.ScriptText:
#load "reference"

using System;
using System.Collections;
////////////////////////////////////////////////////////////////////////////////////////////////
//
// Application: Lenze 8400 Motec
// Lenze 8400 Motec frequency converter
// 
// Created: 04.08.2022
// By: F.EE (FelixC)
//
////////////////////////////////////////////////////////////////////////////////////////////////

////////////////////////////////////////////////////////////////////////////////////////////////
//Safety controlDword
////////////////////////////////////////////////////////////////////////////////////////////////
ConvertFunctions.UIntToBool(I_PLC_PO_F_ControlDword,

x00: out _Bit_24_PO_F,      //Reserve
x01: out _Bit_25_PO_F,      //Reserve
x02: out _Bit_26_PO_F,      //Reserve
x03: out _Bit_27_PO_F,      //Reserve
x04: out _Bit_28_PO_F,      //Reserve
x05: out _Bit_29_PO_F,      //Reserve
x06: out _Bit_30_PO_F,      //Reserve
x07: out _Bit_31_PO_F,     //Reserve
x08: out _PS_AIS_PO_F,      //0 -> 1 Wiederanlaufquittierung auslösen
x09: out _PS_AIE_PO_F,      //0 -> 1 Fehlerquittierung auslösen
x10: out _Bit_18_PO_F,      //Reserve
x11: out _Bit_19_PO_F,      //Reserve
x12: out _Bit_20_PO_F,      //Reserve
x13: out _Bit_21_PO_F,      //Reserve
x14: out _Bit_22_PO_F,      //Reserve
x15: out _SSE_PO_F,         //0= SSE Funktion ist aktiviert
x16: out _Bit_8_PO_F,       //Reserve
x17: out _ES_PO_F,          //Zustimmung aktiv
x18: out _Bit_10_PO_F,      //Reserve
x19: out _OMS_PO_F,         //0= Normalbetrieb, 1= Sonderbetrieb
x20: out _Bit_12_PO_F,      //Reserve
x21: out _Bit_13_PO_F,      //Reserve
x22: out _Bit_14_PO_F,      //Reserve
x23: out _Bit_15_PO_F,      //Reserve
x24: out _STO_PO_F,         //STO Funktion ist aktiviert
x25: out _SS1_PO_F,         //SS1 Funktion ist aktiviert
x26: out _Bit_2_PO_F,       //Reserve
x27: out _Bit_3_PO_F,       //Reserve
x28: out _Bit_4_PO_F,       //Reserve
x29: out _Bit_5_PO_F,       //Reserve
x30: out _Bit_6_PO_F,       //Reserve
x31: out _Bit_7_PO_F);       //Reserve

_STO_active_PI_F = !_STO_PO_F;               //STO Funktion ist aktiv
_SS1_active_PI_F = !_SS1_PO_F;               //SS1 Funktion ist aktiv
_ES_active_PI_F = _ES_PO_F;                 //Sicherer Zustimmtaster ist aktiv
_OMS_active_PI_F = _OMS_PI_F = _OMS_PO_F;   //Sonderbetrieb ist aktiv
_SSE_active_PI_F = !_SSE_PO_F;               //SSE Funktion ist aktiv


////////////////////////////////////////////////////////////////////////////////////////////////
//Safety StatusDword
////////////////////////////////////////////////////////////////////////////////////////////////
O_PLC_PI_F_StatusDword = ConvertFunctions.BoolToUint(
x00: _SD_In1_PI_F,          //Sensor an I1A und I1B: Kanäle A und B sind im EIN-Zustand
x01: _SD_In2_PI_F,          //Sensor an I2A und I2B: Kanäle A und B sind im EIN-Zustand
x02: _Bit_26_PI_F,          //Reserve
x03: _Bit_27_PI_F,          //Reserve
x04: _Bit_28_PI_F,          //Reserve
x05: _OMS_active_PI_F,      //Sonderbetrieb ist aktiv
x06: _Bit_30_PI_F,          //Reserve
x07: _Error_active_PI_F,   //Fehlerzustand ist aktiv
x08: _Bit_16_PI_F,          //Reserve
x09: _Bit_17_PI_F,          //Reserve
x10: _Bit_18_PI_F,          //Reserve
x11: _Bit_19_PI_F,          //Reserve
x12: _Bit_20_PI_F,          //Reserve
x13: _Bit_21_PI_F,          //Reserve
x14: _Bit_22_PI_F,          //Reserve
x15: _SSE_active_PI_F,      //SSE Funktion ist aktiv
x16: _Bit_8_PI_F,           //Reserve
x17: _ES_active_PI_F,       //Sicherer Zustimmtaster ist aktiv
x18: _Bit_10_PI_F,          //Reserve
x19: _OMS_PI_F,             //0= Normal Betrieb, 1= Sonder Betrieb 
x20: _Bit_12_PI_F,          //Reserve
x21: _Bit_13_PI_F,          //Reserve
x22: _Bit_14_PI_F,          //Reserve
x23: _Bit_15_PI_F,          //Reserve
x24: _STO_active_PI_F,      //STO Funktion ist aktiv
x25: _SS1_active_PI_F,      //SS1 Funktion ist aktiv
x26: _Bit_2_PI_F,           //Reserve
x27: _Bit_3_PI_F,           //Reserve
x28: _Bit_4_PI_F,           //Reserve
x29: _Bit_5_PI_F,           //Reserve
x30: _Bit_6_PI_F,           //Reserve
x31: _Bit_7_PI_F);          //Reserve

////////////////////////////////////////////////////////////////////////////////////////////////
//controlword
////////////////////////////////////////////////////////////////////////////////////////////////
ConvertFunctions.UShortToBool(I_PLC_PO_0_Controlword,

x00: out _PO_0_SwitchOn,        //Wechsel in Switch on
x01: out _PO_0_DisableVoltage,  //Wechselrichteransteuerung sperren
x02: out _PO_0_SetQuickStop,    //Schnellhalt
x03: out _PO_0_EnableOperation, //Antriebsregler freigeben
x04: out _PO_0_bTI1,            //2.Rampe aktivieren. Einstellung in C101/1 und C103/1
x05: out _PO_0_JogCtrl_1,       //Aktivierung der Eingangsauswahl
x06: out _PO_0_JogCtrl_2,       //Aktivierung der Eingangsauswahl
x07: out _PO_0_ResetFault,     //Fehler zurücksetzen
x08: out _PO_0_SetHalt,         //Abrampen des Sollwertgenerators
x09: out _PO_0_bOut1,           //Digitaler Ausgang 1 (X42) C0116
x10: out _PO_0_bOut2,           //Digitaler Ausgang 1 (X42) C0116
x11: out _PO_0_BrakeRelease,    //Bremse öffnen
x12: out _PO_0_JogSpeed1,       //Aktivierung der Festsollwerte 1 ...3
x13: out _PO_0_JogSpeed2,       //Aktivierung der Festsollwerte 1 ...3
x14: out _PO_0_SetFail,         //Fehler setzen
x15: out _PO_0_SetSpeedCcw);     //Linksdrehrichtung aktiv (CCW)

////////////////////////////////////////////////////////////////////////////////////////////////
//Logic
////////////////////////////////////////////////////////////////////////////////////////////////

//Speed
_reqSpeedPlcFloat = (float)I_PLC_PO_1_MainSetValue;

_used_Speed_percent = 0;

if (_PO_0_JogSpeed1 && !_PO_0_JogSpeed2)
{
    _used_Speed_percent = Para_JogSpeed_1;
}
else if (!_PO_0_JogSpeed1 && _PO_0_JogSpeed2)
{
    _used_Speed_percent = Para_JogSpeed_2;
}
else if (_PO_0_JogSpeed1 && _PO_0_JogSpeed2)
{
    _used_Speed_percent = Para_JogSpeed_3;
}
else
{
    _used_Speed_percent = _reqSpeedPlcFloat / Para_Transmissionfactor_Speed;
}

if (_PO_0_SetSpeedCcw)
{
    _used_Speed_percent *= -1;
}


//drive SIM
var drive = !_PO_0_SetHalt && _PO_0_SwitchOn && !_PO_0_DisableVoltage && !_PO_0_SetQuickStop && _PO_0_EnableOperation;

SIM_Result_Speed_Percentage = 0;
if(drive)
{
    SIM_Result_Speed_Percentage = _used_Speed_percent;
}


//signals
if (!_PO_0_SetHalt)
{
    _PI_0_StatusCodeBit0=true;
    _PI_0_StatusCodeBit1=false;
    _PI_0_StatusCodeBit2=true;
    _PI_0_StatusCodeBit3=false;

    _PI_0_DriveReady=true;
}

else if (_PO_0_SwitchOn)
{
    _PI_0_StatusCodeBit0=false;
    _PI_0_StatusCodeBit1=false;
    _PI_0_StatusCodeBit2=true;
    _PI_0_StatusCodeBit3=false;

    _PI_0_DriveReady=true;
}

else
{
    _PI_0_StatusCodeBit0=true;
    _PI_0_StatusCodeBit1=true;
    _PI_0_StatusCodeBit2=false;
    _PI_0_StatusCodeBit3=false;

    _PI_0_DriveReady=false;
}

_PI_0_QspIsActive = _PO_0_SetQuickStop; // Quickstop

_PI_0_JogCtrlBit1active = _PO_0_JogCtrl_1;
_PI_0_JogCtrlBit2active = _PO_0_JogCtrl_2;

_PI_0_BrkReleased = _PO_0_BrakeRelease;

_PI_0_ActSpeedIsZero = Math.Abs(SIM_Result_Speed_Percentage) < 0.001f;
_PI_0_ControllerInhibit = _PO_0_SetHalt; //!_PO_0_EnableOperation; //Antrieb ist gesperrt

////////////////////////////////////////////////////////////////////////////////////////////////
//Statusword
////////////////////////////////////////////////////////////////////////////////////////////////
O_PLC_PI_0_Statusword = ConvertFunctions.BoolToUShort(
x00: _PI_0_DriveFail,
x01: _PI_0_PowerDisabled,       //Wechselrichter ist freigegeben
x02: _PI_0_DriveReady,          //Antrieb ist betriebsbereit
x03: _PI_0_SpeedCcw,            //Drehrichtung
x04: _PI_0_QspIsActive,         //Quickstopp ist aktiv, Antrieb wird geführt runtergefahren
x05: _PI_0_BrkReleased,         //Bremse ist gelüftet
x06: _PI_0_ActSpeedIsZero,      // aktuelle Drehzahl ist 0
x07: _PI_0_ControllerInhibit,  //Antrieb ist gesperrt
x08: _PI_0_StatusCodeBit0,     //Statuscode Wetigkeit 1
x09: _PI_0_StatusCodeBit1,     //Statuscode Wetigkeit 2
x10: _PI_0_StatusCodeBit2,     //Statuscode Wetigkeit 4
x11: _PI_0_StatusCodeBit3,     //Statuscode Wetigkeit 8
x12: _PI_0_Warning,             //Warnung
x13: _PI_0_Trouble,             //Antrieb ist im Zustand Trouble
x14: _PI_0_JogCtrlBit1active,   //Spiegelung Steuerword Bit 5 - InputSel1
x15: _PI_0_JogCtrlBit2active);   //Spiegelung Steuerword Bit 5 - InputSel2



////////////////////////////////////////////////////////////////////////////////////////////////
//Status speed
////////////////////////////////////////////////////////////////////////////////////////////////
O_PLC_PI_1_Speed = 0;
if (drive)
{
 _used_Speed = _used_Speed_percent * Para_Transmissionfactor_Speed /100;
O_PLC_PI_1_Speed = (short)_used_Speed;
}



////////////////////////////////////////////////////////////////////////////////////////////////
// Result Speed Real
////////////////////////////////////////////////////////////////////////////////////////////////

SIM_Result_Speed = (SIM_Result_Speed_Percentage / 100) * SIM_MaxSpeed;
